style.css:
@-moz-document url-prefix("https://") {
/* Fondo general: rosa pastel */
body, html {
    background: #ffdce8 !important;  /* rosa pastel claro */
    color: #ffffff !important;       /* texto blanco */
}

/* Texto blanco en todo */
* {
    color: #ffffff !important;
}

/* Banners superiores (header) rosa pastel oscuro */
header, 
.topbar, 
.navbar, 
#header, 
div[role="banner"] {
    background: #e08cb0 !important;  /* rosa pastel oscuro */
}

/* Barra lateral rosa pastel oscuro */
aside,
.sidebar,
#sidebar,
.nav-sidebar,
.left-menu,
.left-panel {
    background: #e08cb0 !important;  /* rosa pastel oscuro */
}

/* Tarjetas, contenedores, paneles: rosa pastel suave */
.card, .panel, .container, .content, main {
    background: #ffdce8 !important;
    color: #ffffff !important;
}

/* Inputs, cajas de texto */
input, textarea, select {
    background: #f7cfe0 !important;
    color: #ffffff !important;
    border: 1px solid #e08cb0 !important;
}

/* Botones */
button, .btn {
    background: #e08cb0 !important;
    color: #ffffff !important;
}
}
